ROOT = Path(__file__).resolve().parents[1]


def read_manuscript(name):
    result = {}
    topic = None
    heading = None
    lines = []
    def finish():
        if topic is not None and heading is not None:
            result[topic].append({'heading': heading, 'text': '\n'.join(lines).strip()})
    for line in (ROOT / 'content/manuscripts' / (name + '.md')).read_text().splitlines():
        if line.startswith('# '):
            finish(); topic = line[2:]; result[topic] = []; heading = None; lines = []
        elif line.startswith('## '):
            finish(); heading = line[3:]; lines = []
        else:
            lines.append(line)
    finish()
    return result

