def enrich_foundation(lang, slug, lesson):
    sections = lesson['sections']
    # Topic explanations precede practice. Remove the former repeated generic
    # study advice; it is replaced by concrete worked material and real cases.
    sections = sections[:3] + [dict(s) for s in FOUNDATION[slug]] + sections[3:5]
    sections[1] = {**sections[1], 'text': RULES[lang][list(FOUNDATION).index(slug)] + '\n\nЭтот фрагмент иллюстрирует тему. Полная программа проверяемого примера приведена отдельно, если у занятия есть автоматическая лабораторная.'}
    lab = lesson.get('challenge')
    if lab:
        sections.insert(-2, {'heading':'Полная программа и проверяемый контракт', 'text':lab['prompt'] + '\n\nСначала сопоставь каждую операцию с объяснённой моделью. Затем закрой решение и напиши собственный вариант. Совпадение вывода не заменяет объяснение границ и причин правильности.', 'code':lab['solution']})
        sections.insert(-2, {'heading':'Конкретные входы и ожидаемые результаты', 'text':'Каждая строка таблицы — отдельный запуск. Переносы строк во вводе значимы. В автоматическом ответе не должно быть дополнительных приглашений или диагностических сообщений.', 'table':{'columns':['Ввод','Ожидаемый вывод'], 'rows':[[t['input'].rstrip('\n'),t['expected']] for t in lab['tests']]}})
    lesson['sections'] = sections
    lesson['questionRevision'] = 3
    lesson['answers'] = ANSWERS[slug]
    lesson['questions'] = QUESTIONS[slug]
    lesson['difficulty'] = 'Основы' if len(slug) and slug in list(FOUNDATION)[:12] else 'Уверенная база'
    lesson['minutes'] = max(45, round(sum(len(s['text'].split()) for s in sections)/140)+35)
    return finish(lesson)


def enrich_advanced(lang, index, lesson):
    family = FAMILIES[lang][index]
    deep = [dict(s) for s in ADVANCED[family] + ADVANCED_CASES[family]]
    sections = lesson['sections']
    sections[1] = {**sections[1], 'text': PROFILES[lang] + '\n\nПример ниже показывает центральную возможность. Фрагменты с несколькими файлами нужно разделить по указанным именам. Дополнительные внешние инструменты требуют отдельного окружения; встроенная IDE не загружает сетевые пакеты автоматически.'}
    sections = sections[:2] + deep + [sections[3]]
    sections.append({'heading':'Разбор собственного решения по контракту', 'text':lesson['assignment'] + '\n\nЗапиши состояние до операции и после неё, включая неуспешный путь. Для каждого ресурса назови владельца, для каждой коллекции — ключ и порядок, для фоновой работы — условие завершения. Покажи не только правильный результат, но и конкретный случай, который отличит его от правдоподобной ошибки. После изменения требования повтори проверки, относящиеся к изменённому контракту.'})
    lesson['sections'] = sections
    lesson['questionRevision'] = 3
    lesson['questions'] = ['Какую проблему решает изученная возможность?', 'Каким конкретным экспериментом проверить её контракт?', 'Какую самостоятельную работу нужно выполнить и что в ней обосновать?']
    lesson['answers'] = [sections[0]['text'],deep[-1]['text'],lesson['assignment']]
    lesson['difficulty'] = 'Проект' if index>=13 else 'Продвинутый уровень'
    return finish(lesson)


def sql_fixture():
    source=(ROOT/'apps/devcat_flutter/lib/core/course.dart').read_text()
    return re.search(r"const sqlFixture = '''\n(.*?)'''",source,re.S)[1]


def enrich_sql(index, slug, lesson):
    sections = lesson['sections']
    sections = sections[:2] + [dict(s) for s in SQL_DEPTH[slug]] + sections[2:4]
    answers = [SQL_GRAIN.get(slug,'Гранулярность и итог операции определяются ключами, ограничениями и контрактом рассматриваемой схемы.')]
    if index<27:
        connection=sqlite3.connect(':memory:');connection.executescript(sql_fixture())
        cursor=connection.execute(lesson['examples'][0]);rows=cursor.fetchall()
        columns=[d[0] for d in cursor.description]
        sections.insert(2,{'heading':'Исходные таблицы для ручной трассировки','text':'customers хранит покупателей, orders — отдельные заказы. У Ани два заказа, у Бориса один, у Веры ни одного. Числа ниже совпадают с основной учебной базой. Независимая автоматическая проверка меняет значения и связи.', 'table':{'columns':['Таблица','id','Имя / customer_id','amount'], 'rows':[['customers','1','Аня','—'],['customers','2','Борис','—'],['customers','3','Вера','—'],['orders','1','1','10'],['orders','2','1','25'],['orders','3','2','40']]}})
        sections.insert(3,{'heading':'Реальный результат приведённого запроса', 'text':'Результат вычисляется SQLite при сборке учебника. Сначала выполни логические этапы вручную, затем сверь значения, число строк и порядок. NULL обозначен явно, а пустой результат не следует путать с ошибкой запроса.', 'table':{'columns':columns,'rows':[['NULL' if v is None else str(v) for v in row] for row in rows]}})
        answers[0] += ' Столбцы данного примера: '+', '.join(columns)+'. Основной набор даёт '+str(len(rows))+' строк.'
        connection.close()
    if index >= 27:
        from sql_worked_labs import sections as worked_sql_sections
        sections.extend(worked_sql_sections(slug))
    sections.append({'heading':'Независимый проверочный сценарий', 'text':'Измени только один смысловой факт за опыт: добавь покупателя без заказов, второй заказ тому же покупателю или двух покупателей с одинаковым именем. Для выбранного изменения сначала вручную укажи ожидаемое число строк и затронутые значения. Затем проверь, сохранилась ли гранулярность и не изменилось ли число фактов из-за соединения.\n\nДля операций изменения работай с отдельной собственной базой. Выполняй команды по одной, проверяй состояние после успеха и отказа, а для сохранения перезапусти приложение. Встроенная учебная база защищена от DDL/DML; собственная база SQL-проекта в IDE предназначена для таких экспериментов.'})
    lesson['sections']=sections
    lesson['answers'] = answers + ['WHERE сохраняет TRUE, а NULL может давать UNKNOWN. Для пустого набора и внешнего соединения отдельно проверяются COUNT, SUM и выбранная подстановка отсутствия. '+SQL_DEPTH[slug][0]['text'].split('\n\n')[-1], 'Проверяй данные с другим количеством связанных строк и значениями на границе. Правильное решение должно сохранять смысл строки и заявленный порядок, а не совпадать только с показанными числами.']
    lesson['difficulty']='Основы SQL' if index<11 else 'Аналитика SQL' if index<27 else 'Проектирование баз'
    return finish(lesson)


def finish(lesson):
    lesson['theory']='\n\n'.join(s['text'] for s in lesson['sections'])
    lesson['readingWords']=len(lesson['theory'].split())
    return lesson

